import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Unified People Avatars, Banner Presets & S3 Image Upload Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/01-identity-gateway/user-avatar-and-banner-presets/spec.md","filePath":"feature/modules/01-identity-gateway/user-avatar-and-banner-presets/spec.md"}'),i={name:"feature/modules/01-identity-gateway/user-avatar-and-banner-presets/spec.md"};function s(n,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="unified-people-avatars-banner-presets-s3-image-upload-pipeline" tabindex="-1">Unified People Avatars, Banner Presets &amp; S3 Image Upload Pipeline <a class="header-anchor" href="#unified-people-avatars-banner-presets-s3-image-upload-pipeline" aria-label="Permalink to &quot;Unified People Avatars, Banner Presets &amp; S3 Image Upload Pipeline&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>user-avatar-and-banner-presets</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>01-identity-gateway</code> — Identity, API Gateway &amp; Edge Security</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>people-avatars</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/02-profile/README.html">3.3 User &amp; Client Profile</a> (<code>3.3.1–3.3.4</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Deliver consistent, zero-broken-image identity rendering (custom S3 avatars, curated illustrated avatar/banner presets, and deterministic initials fallback) across every user-facing surface in BrandHub: Sidebar, Agency/Workspace participant tables, Task assignees &amp; comments, Workspace Chat, Approval trails, and Admin Account tables.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, or <code>Admin</code>, I want my custom uploaded avatar/banner or selected preset to appear consistently across every Workspace, Task, Chat message, and Profile card without broken image icons or layout shifts.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Three-Tier Avatar Resolution (<code>people-avatars</code>):</strong> Resolves <code>avatarUrl</code> (S3/CDN <code>/api/v1/public/images/**</code> or OAuth picture) -&gt; curated BrandHub preset identifier -&gt; deterministic WCAG-contrasted initials badge derived from <code>fullName</code> / <code>email</code>.</li><li><strong>Custom S3 Crop &amp; Upload (<code>UserController</code>):</strong> <code>POST /api/v1/users/me/avatar</code> and <code>POST /api/v1/users/me/banner</code> validate MIME magic bytes (<code>JPEG</code>, <code>PNG</code>, <code>WebP</code>, <code>&lt;= 5 MB</code>), crop/normalize via <code>ImageCropperModal.tsx</code>, upload to S3, and update <code>users.avatar_url</code> / <code>banner_url</code>.</li><li><strong>Universal Surface Rollout:</strong> Shared <code>UserAvatar</code> primitive renders identically across Agency member rosters, Workspace rosters, Task Kanban/Table/Detail/Comments, Chat channels/threads/calls, Collaborator/Client cards, and Admin User Directory.</li><li><strong>Graceful Broken-URL Fallback:</strong> Image <code>onError</code> transitions smoothly to deterministic initials without retry loops or layout jitter.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>profile.avatar.{upload,choosePreset,cropTitle,remove,sizeLimitError}</code> in <code>src/i18n/locales/{vi,en}/profile.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>components/shared/image-editor/ImageCropperModal.tsx</code>, shared <code>UserAvatar</code> component across <code>pages/{agency,workspace,tasks,chat,admin}/*</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/settings/AccountSettingsScreen.tsx</code> (<code>expo-image-picker</code> + <code>expo-image-manipulator</code> + <code>expo-image</code>)</li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/users/me/avatar</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client, Admin</code>)</td><td style="text-align:left;"><code>UserController.uploadAvatar()</code> -&gt; S3 upload + <code>users.avatar_url</code> update</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/users/me/banner</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client, Admin</code>)</td><td style="text-align:left;"><code>UserController.uploadBanner()</code> -&gt; S3 upload + <code>users.banner_url</code> update</td></tr><tr><td style="text-align:left;"><code>PUT /api/v1/users/me</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client, Admin</code>)</td><td style="text-align:left;"><code>UserController.updateMe()</code> -&gt; persists preset key or profile metadata</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/public/images/**</code></td><td style="text-align:left;">Public Read (Cached)</td><td style="text-align:left;"><code>PublicImageController</code> -&gt; serves public avatar/banner/logo assets with cache headers</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Oversize / Disguised SVG or Executable:</strong> Rejected <code>400/413</code> by server-side magic-byte inspection (SVG disallowed for user avatars to prevent stored XSS).</li><li><strong>Deactivated User Historical Attribution:</strong> Historical Task comments and Chat messages retain non-clickable display name and fallback avatar.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/02-profile/README.html">3.3 User &amp; Client Profile</a> (<code>3.3.1–3.3.4</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA 02 Authentication &amp; Profile</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
